          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, attr_status_code, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name='POST' GROUP BY ALL",
          "claim": "Preserve's outgoing POST client spans: 1497 Error spans at about 1.4 ms p95, versus 2992 Unset spans with server children."
        },
        {
          "kind": "log",
          "sql": "SELECT message, COUNT(*) n FROM abnormal_logs WHERE service_name='ts-preserve-service' AND level='SEVERE' GROUP BY 1 ORDER BY n DESC",
          "claim": "Preserve logs SEVERE exceptions: ResourceAccessException 'I/O error on POST request ... Connection reset' to travel and basic services."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, COUNT(*) n FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name='PreserveController.preserve' GROUP BY ALL",
          "claim": "Preserve's controller span fails in 1498 requests, while downstream callee spans (travel, basic, security, contacts) return 200."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code st, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE span_name IN ('POST /api/v1/preserveservice/preserve') GROUP BY ALL",
          "claim": "ui-dashboard's preserve requests return HTTP 500 Error in 1498 spans, matching preserve's failing server spans, p95 about 541 ms."
        }
      ]
    }
  ]
}
